import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    os_type = platform.system()
    if os_type == "Windows":
        cmd = ["wmic", "cpu", "get", "loadpercentage"]
    else:
        cmd = ["mpstat", "1", "1"]
    data = []
    iterations = int(duration // interval)
    for i in range(iterations):
        timestamp = time.time()
        try:
            output = subprocess.check_output(cmd, shell=True).decode()
            if os_type == "Windows":
                lines = output.strip().split("\n")
                cpu_usage = lines[1].strip()
            else:
                lines = output.strip().split("\n")
                last_line = lines[-1]
                parts = last_line.split()
                cpu_usage = parts[-1]
            data.append({"timestamp": timestamp, "cpu_usage": float(cpu_usage)})
        except:
            data.append({"timestamp": timestamp, "cpu_usage": None})
        if i < iterations - 1:
            time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(data, f)
    except IOError:
        return None
    return LOGFILE_PATH

